const calculateMonthlyAttendanceSummary = (students, attendanceRecords, yearMonth) => {
  const monthRecords = attendanceRecords.filter((r) => r.date.startsWith(yearMonth));
  const totalDays = monthRecords.length;
  return students.slice().sort((a, b) => a.rollNumber - b.rollNumber).map((s) => {
    let presentDays = 0;
    let absentDays = 0;
    let leaveDays = 0;
    for (const record of monthRecords) {
      const st = record.records[s.id];
      if (st === "present") presentDays++;
      else if (st === "absent") absentDays++;
      else if (st === "leave") leaveDays++;
    }
    const percentage = totalDays > 0 ? Math.round(presentDays / totalDays * 100) : 0;
    return {
      studentId: s.id,
      rollNumber: s.rollNumber,
      name: s.name,
      gender: s.gender,
      totalDays,
      presentDays,
      absentDays,
      leaveDays,
      percentage
    };
  });
};
